package org.humanjourney.core.mapfeature;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import org.mockito.MockedStatic;
import net.minecraft.SharedConstants;
import net.minecraft.server.Bootstrap;
import static org.humanjourney.core.mapfeature.GeometryV2Test.*;
class GeometryV2ProtocolTest {
 static MockedStatic<net.minecraftforge.fml.ModLoader> loader;static FeatureGeometry LARGE;
 @BeforeAll static void bootstrap(){loader=mockStatic(net.minecraftforge.fml.ModLoader.class);loader.when(net.minecraftforge.fml.ModLoader::get).thenReturn(mock(net.minecraftforge.fml.ModLoader.class));SharedConstants.tryDetectVersion();Bootstrap.bootStrap();LARGE=large();}
 @AfterAll static void closeLoader(){loader.close();}
 static List<FeaturePackets.Frame> frames(long n,MapFeature.View f){return FeatureProtocolTest.full(n,List.of(f));}
 static FeaturePackets.Frame wire(FeaturePackets.Frame f){var b=FeatureProtocolTest.buffer();try{FeaturePackets.CODEC.encode(b,f);assertTrue(b.readableBytes()<=FeaturePackets.MAX_BYTES);var copy=FeaturePackets.CODEC.decode(b);assertEquals(f,copy);return copy;}finally{b.release();}}
 @Test void holesAndMultipartRoundTripNativeCodec(){for(String json:List.of(polygon("holes",OUTER,"["+HOLE+"]",1),multipart("multi"))){var f=feature(json).view();var mirror=new ClientFeatureState();for(var frame:frames(1,f))mirror.accept(wire(frame));assertEquals(f,mirror.snapshot().features().get(f.id()));assertFalse(mirror.snapshot().index().hover(f.dimension(),75,75,5).feature()!=null);}}
 @Test void valid4096PointFeatureFragmentsIntoBoundedPacketsAndPublishesAtomically(){var f=view("large",LARGE);var frames=frames(2,f);assertTrue(frames.size()>1);assertTrue(frames.stream().allMatch(p->p.features().isEmpty()&&p.fragments().size()==1));var mirror=new ClientFeatureState();FeatureProtocolTest.apply(mirror,FeatureProtocolTest.full(1,List.of(FeatureProtocolTest.view("old"))));for(int i=frames.size()-1;i>0;i--){assertFalse(mirror.accept(wire(frames.get(i))));assertEquals(Set.of("old"),mirror.snapshot().features().keySet());}assertTrue(mirror.accept(wire(frames.getFirst())));assertEquals(Map.of("large",f),mirror.snapshot().features());}
 @Test void largeSingleOuterRingAlsoUsesFragmentation(){var f=view("large_ring",FeatureGeometry.polygon(new FeatureGeometry.Part(circle(4096,0,0,1000),List.of())));var mirror=new ClientFeatureState();for(var part:frames(1,f))mirror.accept(wire(part));assertEquals(f,mirror.snapshot().features().get(f.id()));}
 @Test void interruptedSnapshotAndStaleLaterFragmentsCannotReplaceNewerState(){var f=view("large",LARGE);var parts=frames(2,f);var mirror=new ClientFeatureState();FeatureProtocolTest.apply(mirror,FeatureProtocolTest.full(1,List.of(FeatureProtocolTest.view("old"))));mirror.accept(parts.getFirst());assertEquals(Set.of("old"),mirror.snapshot().features().keySet());FeatureProtocolTest.apply(mirror,FeaturePackets.frames(FeatureProtocolTest.h(3),FeaturePackets.Mode.CLEAR,0,List.of(),List.of()));parts.forEach(mirror::accept);assertEquals(0,mirror.snapshot().count());}
 @Test void duplicateFragmentsAndMissingFragmentsAreRejected(){var parts=frames(1,view("large",LARGE));var fragments=new ArrayList<FeaturePackets.Fragment>();parts.forEach(f->fragments.addAll(f.fragments()));var incomplete=new ArrayList<>(fragments);incomplete.removeLast();assertThrows(RuntimeException.class,()->FeaturePackets.assemble(incomplete));fragments.add(fragments.getFirst());assertThrows(RuntimeException.class,()->FeaturePackets.assemble(fragments));}
 @Test void fragmentIdentityMismatchKeepsLastValidClientGeometry(){var parts=frames(2,view("large",LARGE));var mirror=new ClientFeatureState();FeatureProtocolTest.apply(mirror,FeatureProtocolTest.full(1,List.of(FeatureProtocolTest.view("old"))));for(var f:parts){var c=f.fragments().getFirst();mirror.accept(new FeaturePackets.Frame(f.header(),f.mode(),f.base(),f.part(),f.parts(),List.of(),List.of(),null,List.of(new FeaturePackets.Fragment("wrong_id",c.index(),c.count(),c.length(),c.data()))));}assertTrue(mirror.needsResync());assertEquals(Set.of("old"),mirror.snapshot().features().keySet());}
 @Test void fragmentPayloadIsImmutableAndDuplicateFramesAreIdempotent(){var frames=frames(1,view("large",LARGE));var mirror=new ClientFeatureState();var first=frames.getFirst();byte[] bytes=first.fragments().getFirst().data();bytes[0]^=1;assertNotEquals(bytes[0],first.fragments().getFirst().data()[0]);assertFalse(mirror.accept(wire(first)));assertFalse(mirror.accept(wire(first)));assertFalse(mirror.needsResync());for(int i=1;i<frames.size();i++)mirror.accept(wire(frames.get(i)));assertEquals(1,mirror.snapshot().count());}
 @Test void unknownV2FeaturesNeverEnterDiscoveredProjectionOrFragments(){var known=feature(polygon("known",OUTER,"["+HOLE+"]",1));var hidden=new MapFeature(view("hidden_large",LARGE),8,2);var data=new FeatureCatalog.Data(Map.of("known",known,"hidden_large",hidden),new FeatureIndex(List.of(known.view(),hidden.view())));var projection=FeatureCatalog.project(data,Set.of("known"));assertEquals(Set.of("known"),projection.keySet());for(var f:FeaturePackets.frames(FeatureProtocolTest.h(1),FeaturePackets.Mode.FULL,0,projection.values(),List.of())){var b=FeatureProtocolTest.buffer();try{FeaturePackets.CODEC.encode(b,f);assertFalse(b.toString(0,b.writerIndex(),java.nio.charset.StandardCharsets.UTF_8).contains("hidden_large"));}finally{b.release();}}}
 @Test void catalogBudgetViolationDuringAtomicCommitDoesNotPublishPartialState(){var mirror=new ClientFeatureState();FeatureProtocolTest.apply(mirror,FeatureProtocolTest.full(1,List.of(FeatureProtocolTest.view("old"))));assertThrows(RuntimeException.class,()->FeaturePackets.frames(FeatureProtocolTest.h(2),FeaturePackets.Mode.FULL,0,Collections.nCopies(257,view("large",LARGE)),List.of()));assertEquals(Set.of("old"),mirror.snapshot().features().keySet());}
 @Test void malformedFragmentMetadataAndPartCountBoundsReject(){assertThrows(RuntimeException.class,()->new FeaturePackets.Fragment("large",0,100,100,new byte[100]));assertThrows(RuntimeException.class,()->new FeaturePackets.Fragment("large",0,1,FeaturePackets.MAX_FEATURE_BYTES+1,new byte[1]));assertThrows(RuntimeException.class,()->new FeaturePackets.Frame(FeatureProtocolTest.h(1),FeaturePackets.Mode.FULL,0,0,FeaturePackets.MAX_PARTS+1,List.of(),List.of(),null));}
}
